mapper.select:
SELECT order_id AS orderId, content, state, price, amount, student_id AS studentId, stock_id AS stockId, created_date AS createdDate
FROM orders
WHERE stock_id = #{stockId}
  AND content = #{content}
  AND state = '대기'
  AND student_id != #{studentId}

      AND price <= #{price}
      ORDER BY price ASC, created_date ASC


      AND price >= #{price}
      ORDER BY price DESC, created_date ASC

mapper.update:
UPDATE stocks
SET publication_balance = publication_balance - #{amount}
WHERE stock_id = #{stockId}

UPDATE orders
SET state = '체결'
WHERE order_id = #{orderId}

UPDATE orders
SET amount = #{amount}
WHERE order_id = #{orderId}

UPDATE orders
SET state = '취소'
WHERE order_id = #{orderId}
